#include "GUI.h"

GUI::GUI()
{
  screenWidth = 0;
  screenHeight = 0;
  maxRadius = 0;
  touchValue_init[0] = 0;
  touchValue_init[1] = 0;
  touchValue_init[2] = 0;
  touchValue_init[3] = 0;
} 

void GUI::init(int touchValue1, int touchValue2, int touchValue3, int touchValue4) {
    screenWidth = M5.Lcd.width();
    screenHeight = M5.Lcd.height();
    maxRadius = screenWidth / 4;

    // 初期のタッチセンサの値を記憶
    touchValue_init[0] = touchValue1;
    touchValue_init[1] = touchValue2;
    touchValue_init[2] = touchValue3;
    touchValue_init[3] = touchValue4;

    // 円の位置を設定
    circlePosition[0][0] = screenWidth / 2; circlePosition[0][1] = screenHeight / 4;   // 上
    circlePosition[1][0] = screenWidth / 4; circlePosition[1][1] = screenHeight / 2;   // 左
    circlePosition[2][0] = screenWidth * 3 / 4; circlePosition[2][1] = screenHeight / 2; // 右
    circlePosition[3][0] = screenWidth / 2; circlePosition[3][1] = screenHeight * 3 / 4; // 下
}

void GUI::drawGUI(int touchValue1, int touchValue2, int touchValue3, int touchValue4) {
    // タッチセンサの値を配列に代入
    int touchValue[4] = {0,0,0,0};
    touchValue[0] = touchValue1;
    touchValue[1] = touchValue2;
    touchValue[2] = touchValue3;
    touchValue[3] = touchValue4;

    // 円のサイズを計算（タッチセンサの値が大きいほど大きな円になる）
    int radius[4] = {0,0,0,0};
    for(int i = 0; i < 4; i++){
      radius[i] = map(touchValue[i], touchValue_init[i] , 250000, 10, maxRadius);
      radius[i] = radius[i]>maxRadius ? maxRadius : radius[i];
    }
    
    // 画面をクリア
    M5.Lcd.fillScreen(TFT_BLACK);

    // 各円を描画
    M5.Lcd.fillCircle(circlePosition[0][0], circlePosition[0][1], radius[0], TFT_RED);    // 上
    M5.Lcd.fillCircle(circlePosition[1][0], circlePosition[1][1], radius[1], TFT_BLUE);   // 左
    M5.Lcd.fillCircle(circlePosition[2][0], circlePosition[2][1], radius[2], TFT_GREEN);  // 右
    M5.Lcd.fillCircle(circlePosition[3][0], circlePosition[3][1], radius[3], TFT_YELLOW); // 下
}